import{_ as d,o as e,a,b as p}from"./app.UgfkfLuP.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"技术附录","link":"/guide/technical_appendix/technical_appendix"},{"text":"C++标准支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_standard_support"},{"text":"Device侧C++语言支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp_language_feature"},{"text":"C++11语言特性","link":"/guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp11_language_feature"}]},"headers":[],"relativePath":"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp11_language_feature.md","filePath":"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp11_language_feature.md","lastUpdated":1792570027000}'),r={name:"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp11_language_feature.md"};function s(c,t,o,n,w,h){return e(),a("div",null,[...t[0]||(t[0]=[p('<div><article class="markdown-body"><h1>C++11语言特性</h1><p>本文介绍C++11语言特性在Ascend C Device侧的支持情况。下表列出C++11核心语言特性在Device侧的支持情况。</p><p><strong>表1</strong> C++11核心语言特性列表</p><table><thead><tr><th>C++11特性</th><th>C++11 Proposal</th><th>是否支持</th><th>说明</th></tr></thead><tbody><tr><td>*this的右值引用（Rvalue references for *this）</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2439.htm">N2439</a></td><td>是</td><td>支持<code>func() &amp;</code>、<code>func() &amp;&amp;</code>、<code>func() const &amp;</code>引用限定成员函数重载。</td></tr><tr><td>右值初始化类对象</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1610.html">N1610</a></td><td>是</td><td>工厂函数返回右值时移动构造或返回值优化均生效。</td></tr><tr><td>变参模板</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2242.pdf">N2242</a></td><td>是</td><td>支持参数包、<code>sizeof...</code>、包展开进数组初始化、函数实参、基类列表，递归继承展开。</td></tr><tr><td>静态断言</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1720.html">N1720</a></td><td>是</td><td>支持命名空间级与函数内<code>static_assert</code>，可在模板中使用。</td></tr><tr><td>auto类型变量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2006/n1984.pdf">N1984</a></td><td>是</td><td>支持从初始化表达式、lambda表达式推导类型。注意Host侧<code>auto dev = nullptr;</code>声明的设备指针经<code>aclrtMalloc</code>传入核函数时Device地址不生效，设备指针应以显式指针类型声明。</td></tr><tr><td>多声明符auto</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1737.pdf">N1737</a></td><td>是</td><td>一条语句声明多个auto变量，要求各声明符推导类型一致，不一致时编译报错。</td></tr><tr><td>Lambda表达式</td><td><a href="https://www.open-std.org/JTC1/SC22/WG21/docs/papers/2009/n2927.pdf">N2927</a></td><td>是</td><td>SIMD与SIMT混合编程场景需显式标记函数属性，详见<a href="./lambda_expressions.html">Lambda表达式</a>。</td></tr><tr><td>表达式的声明类型（Declared type of an expression，decltype）</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2343.pdf">N2343</a></td><td>是</td><td>值类别语义与标准一致：具名实体推导声明类型，表达式按左值、右值推导引用。</td></tr><tr><td>右尖括号</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2005/n1757.html">N1757</a></td><td>是</td><td>嵌套模板关闭符<code>&gt;&gt;</code>无需空格分隔。</td></tr><tr><td>别名模板</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2258.pdf">N2258</a></td><td>是</td><td>支持<code>template &lt;typename T&gt; using Alias = ...</code>及元函数级联。</td></tr><tr><td>空指针常量（Null pointer constant，nullptr）</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2431.pdf">N2431</a></td><td>是</td><td>支持nullptr初始化、比较与函数重载决议。</td></tr><tr><td>强类型枚举</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2347.pdf">N2347</a></td><td>是</td><td>支持enum class及底层类型指定。</td></tr><tr><td>对齐支持</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2341.pdf">N2341</a></td><td>是</td><td>支持alignas、alignof，可作用于类、全局与局部变量。</td></tr><tr><td>条件支持行为</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1627.pdf">N1627</a></td><td>是</td><td><code>__int128</code>扩展整型在Device侧可用。</td></tr><tr><td>委托构造函数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2006/n1986.pdf">N1986</a></td><td>是</td><td>支持构造函数委托链。</td></tr><tr><td>显式转换运算符</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2437.pdf">N2437</a></td><td>是</td><td>支持<code>explicit operator T</code>。</td></tr><tr><td>新字符类型</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2249.html">N2249</a></td><td>是</td><td>支持char16_t、char32_t作为算术类型参与运算。</td></tr><tr><td>字面量中的通用字符名</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2170.html">N2170</a></td><td>是</td><td>支持UCN的UTF-8落地形式。</td></tr><tr><td>标准布局类型</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2342.htm">N2342</a></td><td>是</td><td><code>std::is_standard_layout</code>判定与标准一致，<code>&lt;type_traits&gt;</code>可在Device侧使用。</td></tr><tr><td>defaulted函数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2346.htm">N2346</a></td><td>是</td><td>构造、拷贝、移动、赋值、析构均支持<code>= default</code>。</td></tr><tr><td>deleted函数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2346.htm">N2346</a></td><td>是</td><td>支持<code>= delete</code>，可构造move-only类型。</td></tr><tr><td>扩展friend声明</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2005/n1791.pdf">N1791</a></td><td>是</td><td>支持模板友元不写<code>&lt;&gt;</code>的扩展形式。</td></tr><tr><td>扩展sizeof</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2253.html">N2253</a>、<a href="https://www.open-std.org/jtc1/sc22/wg21/docs/cwg_defects.html#850">DR850</a></td><td>是</td><td>支持类成员sizeof且无需实例，以及<code>sizeof...</code>参数包。</td></tr><tr><td>定义移动特殊成员函数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2010/n3053.html">N3053</a></td><td>是</td><td>支持移动构造与移动赋值的定义、使用。</td></tr></tbody></table><p>下表汇总了Device侧对C++11收录的C99特性的支持情况</p><p><strong>表2</strong> C99特性列表</p><table><thead><tr><th>C99特性</th><th>C++11 Proposal</th><th>支持情况</th><th>说明</th></tr></thead><tbody><tr><td>__func__预定义标识符</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2340.htm">N2340</a></td><td>是</td><td>函数内隐式静态字符串数组可用。</td></tr><tr><td>C99预处理器</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1653.htm">N1653</a></td><td>是</td><td>支持可变参数宏<code>__VA_ARGS__</code>、记号粘贴<code>##</code>、字符串化<code>#</code>。GNU扩展<code>##__VA_ARGS__</code>空参吞并在可变参数为空时不可用，需以函数重载等方式替代。</td></tr><tr><td>long long</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2005/n1811.pdf">N1811</a></td><td>是</td><td>至少64位，支持LL、ULL后缀与宽位数算术。</td></tr><tr><td>扩展整型</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2006/n1988.pdf">N1988</a></td><td>是</td><td><code>&lt;stdint.h&gt;</code>与<code>&lt;cinttypes&gt;</code>的intmax_t、uintmax_t、INT64_C等在Device侧可用。</td></tr></tbody></table></article></div>',1)])])}const l=d(r,[["render",s]]);export{_ as __pageData,l as default};
